import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_labels_rounded_spans(self):
        spans = [Span(543, 1034), Span(480, 720)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)", "08:00-12:00 (4h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(60, 62)], 15)


if __name__ == "__main__":
    unittest.main()
